import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import "./index.css";

export default function CompiladorView() {
    const [codigo, setCodigo] = useState("");
    const [resultado, setResultado] = useState("");
    const [linhas, setLinhas] = useState(["1"]); // Armazena a numeração das linhas
    const textareaRef = useRef(null); // Referência para o textarea

    // Atualiza a numeração das linhas conforme o texto muda
    useEffect(() => {
        const totalLinhas = codigo.split("\n").length;
        setLinhas(Array.from({ length: totalLinhas }, (_, i) => i + 1));
    }, [codigo]);

    // Ajusta a altura automaticamente
    useEffect(() => {
        if (textareaRef.current) {
            textareaRef.current.style.height = "auto";
            textareaRef.current.style.height = textareaRef.current.scrollHeight + "px";
        }
    }, [codigo]);

    // Função para carregar o conteúdo de um arquivo .txt
    const carregarArquivo = (event) => {
        const file = event.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (e) => {
                setCodigo(e.target.result); // Insere o conteúdo no textarea
            };
            reader.readAsText(file); // Lê o arquivo como texto
        }
    };

    // Função para enviar o código ao backend
    const analisarCodigo = async () => {
        try {
            const response = await axios.post("http://localhost:8080/api/compilador/analisar", codigo, {
                headers: { "Content-Type": "text/plain" },
            });
            setResultado(response.data); // Exibe o resultado
        } catch (error) {
            setResultado(error.response?.data || "Erro ao analisar código.");
        }
    };

    return (
        <div style={{ padding: "20px", fontFamily: "Arial" }}>
            <h1>Compilador Comida</h1>

            {/* Input para carregar arquivo */}
            <input type="file" accept=".txt" onChange={carregarArquivo} />
            <br /><br />

            {/* Editor de código com numeração de linhas */}
            <div className="editor-container">
                <div className="line-numbers">
                    {linhas.map((num) => (
                        <div key={num} className="line-number">{num}</div>
                    ))}
                </div>
                <textarea
                    ref={textareaRef}
                    className="codigo-editor"
                    value={codigo}
                    onChange={(e) => setCodigo(e.target.value)}
                    placeholder="Cole ou carregue um arquivo de código..."
                />
            </div>

            <br />
            <button onClick={analisarCodigo}>Cozinhar</button>

            <h2>Resultado:</h2>
            <pre>{resultado}</pre>
        </div>
    );
}
